static bool
c_string_buffer_spec(ptr_uint_t address, pointer_buffer_spec_t *spec)
{
    uint i;
    if (address == 0)
        return false;
    spec->size = 0;
    spec->truncated = true;
    for (i = 0; i < SIDE_EFFECT_VALUE_MAX; ++i) {
        char ch = '\0';
        size_t bytes_read = 0;
        if (!dr_safe_read((void *)(address + i), sizeof(ch), &ch, &bytes_read) ||
            bytes_read != sizeof(ch)) {
            spec->size = i;
            spec->truncated = true;
            return i > 0;
        }
        spec->size = (uint64_t)i + 1;
        if (ch == '\0') {
            spec->truncated = false;
            return true;
        }
    }
    spec->size = SIDE_EFFECT_VALUE_MAX;
    spec->truncated = true;
    return true;
}

static bool
w_string_buffer_spec(ptr_uint_t address, pointer_buffer_spec_t *spec)
{
    uint i;
    if (address == 0)
        return false;
    spec->size = 0;
    spec->truncated = true;
    for (i = 0; i + 1 < SIDE_EFFECT_VALUE_MAX; i += 2) {
        uint16_t ch = 0;
        size_t bytes_read = 0;
        if (!dr_safe_read((void *)(address + i), sizeof(ch), &ch, &bytes_read) ||
            bytes_read != sizeof(ch)) {
            spec->size = i;
            spec->truncated = true;
            return i > 0;
        }
        spec->size = (uint64_t)i + sizeof(ch);
        if (ch == 0) {
            spec->truncated = false;
            return true;
        }
    }
    spec->size = SIDE_EFFECT_VALUE_MAX;
    spec->truncated = true;
    return true;
}

static bool
process_environment_block_size(ptr_uint_t address, bool wide, uint64_t *size_out)
{
    uint64_t offset = 0;
    bool previous_zero = false;
    if (size_out == NULL)
        return false;
    *size_out = 0;
    if (address == 0)
        return false;
    while (offset < SIDE_EFFECT_ENV_BLOCK_MAX) {
        bool is_zero = false;
        size_t bytes_read = 0;
        if (wide) {
            uint16_t ch = 0;
            if (!dr_safe_read((void *)(address + offset), sizeof(ch), &ch,
                              &bytes_read) ||
                bytes_read != sizeof(ch))
                return false;
            is_zero = ch == 0;
            offset += sizeof(ch);
        } else {
            char ch = '\0';
            if (!dr_safe_read((void *)(address + offset), sizeof(ch), &ch,
                              &bytes_read) ||
                bytes_read != sizeof(ch))
                return false;
            is_zero = ch == '\0';
            offset += sizeof(ch);
        }
        if (is_zero && previous_zero) {
            *size_out = offset;
            return true;
        }
        previous_zero = is_zero;
    }
    return false;
}

static bool
environment_block_buffer_spec(ptr_uint_t address, bool wide, pointer_buffer_spec_t *spec)
{
    uint64_t size = 0;
    if (spec == NULL ||
        !process_environment_block_size(address, wide, &size) || size == 0)
        return false;
    spec->size = size;
    spec->truncated = size > SIDE_EFFECT_VALUE_MAX;
    return true;
}

static bool
fixed_buffer_spec(reg_t address, reg_t size, pointer_buffer_spec_t *spec)
{
    if (address == 0 || size == 0)
        return false;
    spec->size = (uint64_t)size;
    spec->truncated = spec->size > SIDE_EFFECT_VALUE_MAX;
    return true;
}

static bool
small_fixed_buffer_spec(reg_t address, uint64_t size, pointer_buffer_spec_t *spec)
{
    if (address == 0 || size == 0)
        return false;
    spec->size = size;
    spec->truncated = size > SIDE_EFFECT_VALUE_MAX;
    return true;
}

static uint64_t
wsa_data_size(void)
{
    return sizeof(void *) == 8 ? 408 : 400;
}

static bool
read_c_string_text(ptr_uint_t address, char *out, size_t out_size, bool *truncated_out)
{
    size_t i;
    if (out == NULL || out_size == 0)
        return false;
    out[0] = '\0';
    if (truncated_out != NULL)
        *truncated_out = false;
    if (address == 0)
        return false;
    for (i = 0; i + 1 < out_size; ++i) {
        char ch = '\0';
        size_t bytes_read = 0;
        if (!dr_safe_read((void *)(address + i), sizeof(ch), &ch, &bytes_read) ||
            bytes_read != sizeof(ch)) {
            out[i] = '\0';
            return i > 0;
        }
        out[i] = ch;
        if (ch == '\0')
            return true;
    }
    out[out_size - 1] = '\0';
    if (truncated_out != NULL)
        *truncated_out = true;
    return out[0] != '\0';
}

static void
append_hex_u16(char *out, size_t out_size, uint16_t value)
{
    static const char hex[] = "0123456789abcdef";
    size_t len;
    if (out == NULL || out_size == 0)
        return;
    len = strlen(out);
    if (len + 6 >= out_size)
        return;
    out[len++] = '\\';
    out[len++] = 'u';
    out[len++] = hex[(value >> 12) & 0xf];
    out[len++] = hex[(value >> 8) & 0xf];
    out[len++] = hex[(value >> 4) & 0xf];
    out[len++] = hex[value & 0xf];
    out[len] = '\0';
}

static bool
read_w_string_text(ptr_uint_t address, char *out, size_t out_size, bool *truncated_out)
{
    size_t i;
    size_t out_len = 0;
    if (out == NULL || out_size == 0)
        return false;
    out[0] = '\0';
    if (truncated_out != NULL)
        *truncated_out = false;
    if (address == 0)
        return false;
    for (i = 0; out_len + 1 < out_size; ++i) {
        uint16_t ch = 0;
        size_t bytes_read = 0;
        if (!dr_safe_read((void *)(address + i * sizeof(ch)), sizeof(ch), &ch,
                          &bytes_read) ||
            bytes_read != sizeof(ch)) {
            out[out_len] = '\0';
            return out_len > 0;
        }
        if (ch == 0) {
            out[out_len] = '\0';
            return true;
        }
        if (ch >= 0x20 && ch < 0x7f && ch != '\\' && ch != '"') {
            out[out_len++] = (char)ch;
            out[out_len] = '\0';
        } else {
            if (out_len + 6 >= out_size)
                break;
            append_hex_u16(out, out_size, ch);
            out_len = strlen(out);
        }
    }
    out[out_size - 1] = '\0';
    if (truncated_out != NULL)
        *truncated_out = true;
    return out[0] != '\0';
}

static bool
read_counted_string_text(ptr_uint_t descriptor, bool wide, char *out, size_t out_size,
                         bool *truncated_out)
{
    uint16_t byte_length = 0;
    reg_t buffer = 0;
    size_t bytes_read = 0;
    ptr_uint_t buffer_field = descriptor + (sizeof(reg_t) == 8 ? 8 : 4);
    size_t out_len = 0;
    uint64_t unit_count;
    uint64_t i;

    if (out == NULL || out_size == 0)
        return false;
    out[0] = '\0';
    if (truncated_out != NULL)
        *truncated_out = false;
    if (descriptor == 0)
        return false;
    if (!dr_safe_read((void *)descriptor, sizeof(byte_length), &byte_length, &bytes_read) ||
        bytes_read != sizeof(byte_length))
        return false;
    if (!dr_safe_read((void *)buffer_field, sizeof(buffer), &buffer, &bytes_read) ||
        bytes_read != sizeof(buffer))
        return false;
    if (byte_length == 0)
        return true;
    if (buffer == 0)
        return false;
    unit_count = wide ? (byte_length / sizeof(uint16_t)) : byte_length;
    for (i = 0; i < unit_count && out_len + 1 < out_size; ++i) {
        if (wide) {
            uint16_t ch = 0;
            if (!dr_safe_read((void *)((ptr_uint_t)buffer + i * sizeof(ch)),
                              sizeof(ch), &ch, &bytes_read) ||
                bytes_read != sizeof(ch))
                return out_len > 0;
            if (ch >= 0x20 && ch < 0x7f && ch != '\\' && ch != '"') {
                out[out_len++] = (char)ch;
                out[out_len] = '\0';
            } else {
                if (out_len + 6 >= out_size)
                    break;
                append_hex_u16(out, out_size, ch);
                out_len = strlen(out);
            }
        } else {
            char ch = '\0';
            if (!dr_safe_read((void *)((ptr_uint_t)buffer + i), sizeof(ch), &ch,
                              &bytes_read) ||
                bytes_read != sizeof(ch))
                return out_len > 0;
            out[out_len++] = ch;
            out[out_len] = '\0';
        }
    }
    if (i < unit_count && truncated_out != NULL)
        *truncated_out = true;
    out[out_size - 1] = '\0';
    return byte_length == 0 || out[0] != '\0';
}

static bool
read_win32_text_or_atom(reg_t value, bool wide, char *out, size_t out_size,
                        bool *truncated_out)
{
    if (out == NULL || out_size == 0)
        return false;
    out[0] = '\0';
    if (truncated_out != NULL)
        *truncated_out = false;
    if (value == 0)
        return false;
    if (((ptr_uint_t)value >> 16) == 0) {
        dr_snprintf(out, out_size, "atom:%llu", (unsigned long long)(value & 0xffff));
        out[out_size - 1] = '\0';
        return true;
    }
    if (wide)
        return read_w_string_text((ptr_uint_t)value, out, out_size, truncated_out);
    return read_c_string_text((ptr_uint_t)value, out, out_size, truncated_out);
}

static bool
format_window_resource_label(const api_call_effect_t *effect, char *out, size_t out_size,
                             bool *truncated_out)
{
    uint class_index;
    uint title_index;
    bool wide;
    char class_name[128];
    char title[128];
    bool class_truncated = false;
    bool title_truncated = false;
    bool title_known = true;
    if (out == NULL || out_size == 0 || effect == NULL)
        return false;
    out[0] = '\0';
    if (truncated_out != NULL)
        *truncated_out = false;
    wide = string_eq_ci(effect->callee_symbol, "CreateWindowExW") ||
           string_eq_ci(effect->callee_symbol, "CreateWindowW");
    if (string_eq_ci(effect->callee_symbol, "CreateWindowExA") ||
        string_eq_ci(effect->callee_symbol, "CreateWindowExW")) {
        class_index = 1;
        title_index = 2;
    } else if (string_eq_ci(effect->callee_symbol, "CreateWindowA") ||
               string_eq_ci(effect->callee_symbol, "CreateWindowW")) {
        class_index = 0;
        title_index = 1;
    } else {
        return false;
    }
    if (class_index >= effect->arg_count ||
        !read_win32_text_or_atom(effect->args[class_index], wide, class_name,
                                 sizeof(class_name), &class_truncated))
        return false;
    title[0] = '\0';
    if (title_index < effect->arg_count && effect->args[title_index] != 0) {
        title_known = read_win32_text_or_atom(effect->args[title_index], wide, title,
                                              sizeof(title), &title_truncated);
    }
    if (!title_known)
        return false;
    dr_snprintf(out, out_size, "window:class=%s,title=%s", class_name, title);
    out[out_size - 1] = '\0';
    if (truncated_out != NULL)
        *truncated_out = class_truncated || title_truncated;
    return true;
}

static bool
format_gdi_resource_label(const api_call_effect_t *effect, char *kind, size_t kind_size,
                          char *label, size_t label_size)
{
    if (effect == NULL || kind == NULL || label == NULL || kind_size == 0 || label_size == 0)
        return false;
    kind[0] = '\0';
    label[0] = '\0';
    if (string_eq_ci(effect->callee_symbol, "CreatePen") && effect->arg_count >= 3) {
        copy_string(kind, kind_size, "gdi_object");
        dr_snprintf(label, label_size, "pen:style=%llu,width=%llu,color=0x%08llx",
                    (unsigned long long)effect->args[0],
                    (unsigned long long)effect->args[1],
                    (unsigned long long)effect->args[2]);
        label[label_size - 1] = '\0';
        return true;
    }
    if ((string_eq_ci(effect->callee_symbol, "CreateSolidBrush") ||
         string_eq_ci(effect->callee_symbol, "CreateHatchBrush")) &&
        effect->arg_count >= 1) {
        copy_string(kind, kind_size, "gdi_object");
        if (string_eq_ci(effect->callee_symbol, "CreateHatchBrush") && effect->arg_count >= 2) {
            dr_snprintf(label, label_size, "brush:hatch=%llu,color=0x%08llx",
                        (unsigned long long)effect->args[0],
                        (unsigned long long)effect->args[1]);
        } else {
            dr_snprintf(label, label_size, "brush:solid:color=0x%08llx",
                        (unsigned long long)effect->args[0]);
        }
        label[label_size - 1] = '\0';
        return true;
    }
    if (string_eq_ci(effect->callee_symbol, "CreateCompatibleDC")) {
        char source_kind[SIDE_EFFECT_RESOURCE_KIND_MAX];
        char source_label[SIDE_EFFECT_RESOURCE_LABEL_MAX];
        copy_string(kind, kind_size, "dc");
        if (effect->arg_count > 0 &&
            lookup_handle_resource_locked(effect->args[0], source_kind, sizeof(source_kind),
                                          source_label, sizeof(source_label))) {
            dr_snprintf(label, label_size, "dc:compatible:%s", source_label);
        } else if (effect->arg_count > 0 && effect->args[0] == 0) {
            copy_string(label, label_size, "dc:compatible:screen");
        } else {
            copy_string(label, label_size, "dc:compatible");
        }
        label[label_size - 1] = '\0';
        return true;
    }
    if (string_eq_ci(effect->callee_symbol, "CreateCompatibleBitmap") &&
        effect->arg_count >= 3) {
        copy_string(kind, kind_size, "gdi_object");
        dr_snprintf(label, label_size, "bitmap:compatible:width=%llu,height=%llu",
                    (unsigned long long)effect->args[1],
                    (unsigned long long)effect->args[2]);
        label[label_size - 1] = '\0';
        return true;
    }
    if (string_eq_ci(effect->callee_symbol, "CreateDIBSection") &&
        effect->arg_count >= 2) {
        api_bitmap_info_t info;
        uint64_t bytes = 0;
        if (!read_api_bitmap_info((ptr_uint_t)effect->args[1], &info))
            return false;
        api_bitmap_bits_size((ptr_uint_t)effect->args[1], 0, &bytes);
        copy_string(kind, kind_size, "gdi_object");
        dr_snprintf(label, label_size,
                    "bitmap:dib:width=%lld,height=%lld,bpp=%u,compression=%u,bytes=%llu",
                    (long long)info.width, (long long)info.height,
                    (unsigned)info.bit_count, (unsigned)info.compression,
                    (unsigned long long)bytes);
        label[label_size - 1] = '\0';
        return true;
    }
    return false;
}

static bool
format_cursor_resource_label(const api_call_effect_t *effect, char *label, size_t label_size,
                             bool *truncated_out)
{
    bool wide;
    bool truncated = false;
    char name[SIDE_EFFECT_RESOURCE_LABEL_MAX];
    if (effect == NULL || label == NULL || label_size == 0 || effect->arg_count < 2)
        return false;
    label[0] = '\0';
    wide = string_eq_ci(effect->callee_symbol, "LoadCursorW");
    if (!read_win32_text_or_atom(effect->args[1], wide, name, sizeof(name), &truncated))
        return false;
    if (effect->args[0] == 0) {
        dr_snprintf(label, label_size, "cursor:system:%s", name);
    } else {
        char kind[SIDE_EFFECT_RESOURCE_KIND_MAX];
        char instance_label[SIDE_EFFECT_RESOURCE_LABEL_MAX];
        if (lookup_handle_resource_locked(effect->args[0], kind, sizeof(kind),
                                          instance_label, sizeof(instance_label))) {
            dr_snprintf(label, label_size, "cursor:%s:%s", instance_label, name);
        } else {
            dr_snprintf(label, label_size, "cursor:instance=0x%llx:%s",
                        (unsigned long long)effect->args[0], name);
        }
    }
    label[label_size - 1] = '\0';
    if (truncated_out != NULL)
        *truncated_out = truncated;
    return true;
}

static bool
format_module_resource_label(const api_call_effect_t *effect, char *label, size_t label_size,
                             bool *truncated_out)
{
    bool wide;
    bool nullable_current_process;
    bool truncated = false;
    char name[SIDE_EFFECT_RESOURCE_LABEL_MAX];
    if (effect == NULL || label == NULL || label_size == 0)
        return false;
    label[0] = '\0';
    nullable_current_process = string_eq_ci(effect->callee_symbol, "GetModuleHandleA") ||
                               string_eq_ci(effect->callee_symbol, "GetModuleHandleW");
    if (nullable_current_process && (effect->arg_count == 0 || effect->args[0] == 0)) {
        copy_string(label, label_size, "module:current_process");
        if (truncated_out != NULL)
            *truncated_out = false;
        return true;
    }
    if (effect->arg_count == 0 || effect->args[0] == 0)
        return false;
    wide = string_eq_ci(effect->callee_symbol, "GetModuleHandleW") ||
           string_eq_ci(effect->callee_symbol, "LoadLibraryW") ||
           string_eq_ci(effect->callee_symbol, "LoadLibraryExW");
    if (!read_win32_text_or_atom(effect->args[0], wide, name, sizeof(name), &truncated))
        return false;
    dr_snprintf(label, label_size, "module:%s", name);
    label[label_size - 1] = '\0';
    if (truncated_out != NULL)
        *truncated_out = truncated;
    return true;
}

static bool
format_ldr_module_resource_label(const api_call_effect_t *effect, char *label,
                                 size_t label_size, bool *truncated_out)
{
    char name[SIDE_EFFECT_RESOURCE_LABEL_MAX];
    bool truncated = false;
    if (effect == NULL || label == NULL || label_size == 0 ||
        !string_eq_ci(effect->callee_symbol, "LdrGetDllHandle") ||
        effect->arg_count <= 2 || effect->args[2] == 0)
        return false;
    label[0] = '\0';
    if (!read_counted_string_text((ptr_uint_t)effect->args[2], true, name,
                                  sizeof(name), &truncated))
        return false;
    dr_snprintf(label, label_size, "module:%s", name[0] == '\0' ? "empty_name" : name);
    label[label_size - 1] = '\0';
    if (truncated_out != NULL)
        *truncated_out = truncated;
    return true;
}

static bool
format_heap_create_resource_label(const api_call_effect_t *effect, char *label,
                                  size_t label_size)
{
    if (effect == NULL || label == NULL || label_size == 0)
        return false;
    label[0] = '\0';
    if (string_eq_ci(effect->callee_symbol, "HeapCreate")) {
        uint64_t flags = effect->arg_count > 0 ? (uint64_t)effect->args[0] : 0;
        uint64_t initial_size = effect->arg_count > 1 ? (uint64_t)effect->args[1] : 0;
        uint64_t maximum_size = effect->arg_count > 2 ? (uint64_t)effect->args[2] : 0;
        dr_snprintf(label, label_size,
                    "heap:create:flags=0x%llx,initial=%llu,maximum=%llu",
                    (unsigned long long)flags,
                    (unsigned long long)initial_size,
                    (unsigned long long)maximum_size);
        label[label_size - 1] = '\0';
        return true;
    }
    if (string_eq_ci(effect->callee_symbol, "RtlCreateHeap")) {
        uint64_t flags = effect->arg_count > 0 ? (uint64_t)effect->args[0] : 0;
        uint64_t base = effect->arg_count > 1 ? (uint64_t)effect->args[1] : 0;
        uint64_t reserve_size = effect->arg_count > 2 ? (uint64_t)effect->args[2] : 0;
        uint64_t commit_size = effect->arg_count > 3 ? (uint64_t)effect->args[3] : 0;
        dr_snprintf(label, label_size,
                    "heap:rtl_create:flags=0x%llx,base=0x%llx,reserve=%llu,commit=%llu",
                    (unsigned long long)flags,
                    (unsigned long long)base,
                    (unsigned long long)reserve_size,
                    (unsigned long long)commit_size);
        label[label_size - 1] = '\0';
        return true;
    }
    return false;
}

static bool
format_thread_resource_label(const api_call_effect_t *effect, char *label, size_t label_size)
{
    if (effect == NULL || label == NULL || label_size == 0 ||
        !string_eq_ci(effect->callee_symbol, "CreateThread") || effect->arg_count < 4)
        return false;
    dr_snprintf(label, label_size, "thread:start=0x%llx,param=0x%llx",
                (unsigned long long)effect->args[2],
                (unsigned long long)effect->args[3]);
    label[label_size - 1] = '\0';
    return true;
}

static const char *
sync_object_type_for_symbol(const char *symbol)
{
    if (starts_with_ci(symbol, "CreateEvent") || starts_with_ci(symbol, "OpenEvent") ||
        string_eq_ci(symbol, "SetEvent") || string_eq_ci(symbol, "ResetEvent") ||
        string_eq_ci(symbol, "PulseEvent"))
        return "event";
    if (starts_with_ci(symbol, "CreateMutex") || starts_with_ci(symbol, "OpenMutex") ||
        string_eq_ci(symbol, "ReleaseMutex"))
        return "mutex";
    if (starts_with_ci(symbol, "CreateSemaphore") ||
        starts_with_ci(symbol, "OpenSemaphore") ||
        string_eq_ci(symbol, "ReleaseSemaphore"))
        return "semaphore";
    return "sync_object";
}

static bool
sync_symbol_is_wide(const char *symbol)
{
    return string_eq_ci(symbol, "CreateEventW") ||
           string_eq_ci(symbol, "OpenEventW") ||
           string_eq_ci(symbol, "CreateMutexW") ||
           string_eq_ci(symbol, "OpenMutexW") ||
           string_eq_ci(symbol, "CreateSemaphoreW") ||
           string_eq_ci(symbol, "OpenSemaphoreW");
}

static bool
sync_name_arg_index(const char *symbol, uint *index)
{
    if (symbol == NULL || index == NULL)
        return false;
    if (starts_with_ci(symbol, "CreateEvent") ||
        starts_with_ci(symbol, "CreateMutex") ||
        starts_with_ci(symbol, "CreateSemaphore")) {
        *index = 3;
        return true;
    }
    if (starts_with_ci(symbol, "OpenEvent") ||
        starts_with_ci(symbol, "OpenMutex") ||
        starts_with_ci(symbol, "OpenSemaphore")) {
        *index = 2;
        return true;
    }
    return false;
}

static bool
capture_sync_name_text(const api_call_effect_t *effect, char *out, size_t out_size,
                       bool *captured_out, bool *truncated_out, reg_t *name_arg_out)
{
    uint index;
    bool truncated = false;
    bool captured = false;
    if (captured_out != NULL)
        *captured_out = false;
    if (truncated_out != NULL)
        *truncated_out = false;
    if (name_arg_out != NULL)
        *name_arg_out = 0;
    if (out != NULL && out_size > 0)
        out[0] = '\0';
    if (effect == NULL || out == NULL || out_size == 0 ||
        !sync_name_arg_index(effect->callee_symbol, &index) || index >= effect->arg_count)
        return false;
    if (name_arg_out != NULL)
        *name_arg_out = effect->args[index];
    if (effect->args[index] == 0)
        return true;
    if (sync_symbol_is_wide(effect->callee_symbol))
        captured = read_w_string_text((ptr_uint_t)effect->args[index], out, out_size,
                                      &truncated);
    else
        captured = read_c_string_text((ptr_uint_t)effect->args[index], out, out_size,
                                      &truncated);
    if (captured_out != NULL)
        *captured_out = captured;
    if (truncated_out != NULL)
        *truncated_out = truncated;
    return captured;
}

static bool
format_sync_resource_label(const api_call_effect_t *effect, char *label, size_t label_size,
                           bool *truncated_out)
{
    const char *object_type;
    uint name_index;
    reg_t name_arg = 0;
    char name[SIDE_EFFECT_RESOURCE_LABEL_MAX];
    bool name_captured = false;
    bool name_truncated = false;
    if (effect == NULL || label == NULL || label_size == 0)
        return false;
    if (!sync_name_arg_index(effect->callee_symbol, &name_index))
        return false;
    label[0] = '\0';
    if (truncated_out != NULL)
        *truncated_out = false;
    object_type = sync_object_type_for_symbol(effect->callee_symbol);
    capture_sync_name_text(effect, name, sizeof(name), &name_captured,
                           &name_truncated, &name_arg);
    if (name_arg != 0 && !name_captured)
        return false;
    if (name_arg != 0) {
        dr_snprintf(label, label_size, "%s:name=%s", object_type, name);
    } else if (starts_with_ci(effect->callee_symbol, "Open")) {
        dr_snprintf(label, label_size, "%s:name=<null>", object_type);
    } else if (string_eq_ci(object_type, "event") && effect->arg_count > 2) {
        dr_snprintf(label, label_size, "event:anonymous:manual=%llu,initial=%llu",
                    (unsigned long long)(effect->args[1] != 0),
                    (unsigned long long)(effect->args[2] != 0));
    } else if (string_eq_ci(object_type, "mutex") && effect->arg_count > 1) {
        dr_snprintf(label, label_size, "mutex:anonymous:initial_owner=%llu",
                    (unsigned long long)(effect->args[1] != 0));
    } else if (string_eq_ci(object_type, "semaphore") && effect->arg_count > 2) {
        dr_snprintf(label, label_size, "semaphore:anonymous:initial=%lld,max=%lld",
                    (long long)(int32_t)effect->args[1],
                    (long long)(int32_t)effect->args[2]);
    } else {
        dr_snprintf(label, label_size, "%s:anonymous", object_type);
    }
    label[label_size - 1] = '\0';
    if (truncated_out != NULL)
        *truncated_out = name_truncated;
    return true;
}

static bool
lookup_fd_resource_locked(int64_t fd, char *kind, size_t kind_size, char *label,
                          size_t label_size)
{
    fd_resource_t *entry;
    if (kind == NULL || kind_size == 0 || label == NULL || label_size == 0)
        return false;
    kind[0] = '\0';
    label[0] = '\0';
    if (fd == 0) {
        copy_string(kind, kind_size, "stdio");
        copy_string(label, label_size, "stdin");
        return true;
    }
    if (fd == 1) {
        copy_string(kind, kind_size, "stdio");
        copy_string(label, label_size, "stdout");
        return true;
    }
    if (fd == 2) {
        copy_string(kind, kind_size, "stdio");
        copy_string(label, label_size, "stderr");
        return true;
    }
    for (entry = fd_resources; entry != NULL; entry = entry->next) {
        if (entry->fd == fd) {
            copy_string(kind, kind_size, entry->kind);
            copy_string(label, label_size, entry->label);
            return true;
        }
    }
    return false;
}

static void
set_fd_resource_locked(int64_t fd, const char *kind, const char *label)
{
    fd_resource_t *entry;
    if (fd < 0 || kind == NULL || kind[0] == '\0' || label == NULL || label[0] == '\0')
        return;
    for (entry = fd_resources; entry != NULL; entry = entry->next) {
        if (entry->fd == fd) {
            copy_string(entry->kind, sizeof(entry->kind), kind);
            copy_string(entry->label, sizeof(entry->label), label);
            return;
        }
    }
    entry = (fd_resource_t *)dr_global_alloc(sizeof(*entry));
    if (entry == NULL)
        return;
    memset(entry, 0, sizeof(*entry));
    entry->fd = fd;
    copy_string(entry->kind, sizeof(entry->kind), kind);
    copy_string(entry->label, sizeof(entry->label), label);
    entry->next = fd_resources;
    fd_resources = entry;
}

static void
delete_fd_resource_locked(int64_t fd)
{
    fd_resource_t **link = &fd_resources;
    while (*link != NULL) {
        fd_resource_t *entry = *link;
        if (entry->fd == fd) {
            *link = entry->next;
            dr_global_free(entry, sizeof(*entry));
            return;
        }
        link = &entry->next;
    }
}

static void
copy_fd_resource_locked(int64_t from_fd, int64_t to_fd)
{
    char kind[SIDE_EFFECT_RESOURCE_KIND_MAX];
    char label[SIDE_EFFECT_RESOURCE_LABEL_MAX];
    if (to_fd < 0)
        return;
    if (lookup_fd_resource_locked(from_fd, kind, sizeof(kind), label, sizeof(label)))
        set_fd_resource_locked(to_fd, kind, label);
    else
        delete_fd_resource_locked(to_fd);
}

static bool
syscall_creates_socket(int sysnum)
{
#if defined(_WIN32)
    (void)sysnum;
    return false;
#elif defined(X64)
    return sysnum == 41;
#else
    return sysnum == 359;
#endif
}

static bool
syscall_accepts_socket(int sysnum)
{
#if defined(_WIN32)
    (void)sysnum;
    return false;
#elif defined(X64)
    return sysnum == 43 || sysnum == 288;
#else
    return sysnum == 364;
#endif
}

static void
socket_resource_label(const reg_t *args, uint arg_count, char *label, size_t label_size)
{
    unsigned long long domain = arg_count > 0 ? (unsigned long long)args[0] : 0;
    unsigned long long type = arg_count > 1 ? (unsigned long long)args[1] : 0;
    unsigned long long protocol = arg_count > 2 ? (unsigned long long)args[2] : 0;
    if (label == NULL || label_size == 0)
        return;
    dr_snprintf(label, label_size, "socket:domain=%llu,type=%llu,protocol=%llu",
                domain, type, protocol);
    label[label_size - 1] = '\0';
}

static void
accepted_socket_resource_label(const char *listener, char *label, size_t label_size)
{
    if (label == NULL || label_size == 0)
        return;
    dr_snprintf(label, label_size, "accepted:%s",
                listener == NULL || listener[0] == '\0' ? "socket" : listener);
    label[label_size - 1] = '\0';
}

