free_fd_resource_cache(void)
{
    fd_resource_t *entry = fd_resources;
    while (entry != NULL) {
        fd_resource_t *next = entry->next;
        dr_global_free(entry, sizeof(*entry));
        entry = next;
    }
    fd_resources = NULL;
}

static bool
lookup_handle_resource_locked(reg_t handle, char *kind, size_t kind_size, char *label,
                              size_t label_size)
{
    handle_resource_t *entry;
    uint32_t hkey = (uint32_t)handle;
    if (kind == NULL || kind_size == 0 || label == NULL || label_size == 0)
        return false;
    kind[0] = '\0';
    label[0] = '\0';
    if (hkey >= 0x80000000u && hkey <= 0x80000006u) {
        copy_string(kind, kind_size, "registry_key");
        switch (hkey) {
        case 0x80000000u:
            copy_string(label, label_size, "HKEY_CLASSES_ROOT");
            return true;
        case 0x80000001u:
            copy_string(label, label_size, "HKEY_CURRENT_USER");
            return true;
        case 0x80000002u:
            copy_string(label, label_size, "HKEY_LOCAL_MACHINE");
            return true;
        case 0x80000003u:
            copy_string(label, label_size, "HKEY_USERS");
            return true;
        case 0x80000004u:
            copy_string(label, label_size, "HKEY_PERFORMANCE_DATA");
            return true;
        case 0x80000005u:
            copy_string(label, label_size, "HKEY_CURRENT_CONFIG");
            return true;
        case 0x80000006u:
            copy_string(label, label_size, "HKEY_DYN_DATA");
            return true;
        default:
            break;
        }
    }
    if (handle == 0 || (reg_t)(ptr_int_t)-1 == handle)
        return false;
    for (entry = handle_resources; entry != NULL; entry = entry->next) {
        if (entry->handle == handle) {
            copy_string(kind, kind_size, entry->kind);
            copy_string(label, label_size, entry->label);
            return true;
        }
    }
    return false;
}

static void
set_handle_resource_locked(reg_t handle, const char *kind, const char *label)
{
    handle_resource_t *entry;
    if (handle == 0 || (reg_t)(ptr_int_t)-1 == handle || kind == NULL ||
        kind[0] == '\0' || label == NULL || label[0] == '\0')
        return;
    for (entry = handle_resources; entry != NULL; entry = entry->next) {
        if (entry->handle == handle) {
            copy_string(entry->kind, sizeof(entry->kind), kind);
            copy_string(entry->label, sizeof(entry->label), label);
            return;
        }
    }
    entry = (handle_resource_t *)dr_global_alloc(sizeof(*entry));
    if (entry == NULL)
        return;
    memset(entry, 0, sizeof(*entry));
    entry->handle = handle;
    copy_string(entry->kind, sizeof(entry->kind), kind);
    copy_string(entry->label, sizeof(entry->label), label);
    entry->next = handle_resources;
    handle_resources = entry;
}

static void
delete_handle_resource_locked(reg_t handle)
{
    handle_resource_t **link = &handle_resources;
    while (*link != NULL) {
        handle_resource_t *entry = *link;
        if (entry->handle == handle) {
            *link = entry->next;
            dr_global_free(entry, sizeof(*entry));
            return;
        }
        link = &entry->next;
    }
}

static void
free_handle_resource_cache(void)
{
    handle_resource_t *entry = handle_resources;
    while (entry != NULL) {
        handle_resource_t *next = entry->next;
        dr_global_free(entry, sizeof(*entry));
        entry = next;
    }
    handle_resources = NULL;
}

