static void
set_com_object_resource_with_payload_locked(ptr_uint_t object,
                                            const char *interface_name,
                                            const char *label,
                                            bool payload_size_captured,
                                            uint64_t payload_size)
{
    com_object_resource_t *entry;
    if (object == 0 || interface_name == NULL || interface_name[0] == '\0' ||
        label == NULL || label[0] == '\0')
        return;
    for (entry = com_object_resources; entry != NULL; entry = entry->next) {
        if (entry->object == object) {
            copy_string(entry->interface_name, sizeof(entry->interface_name),
                        interface_name);
            copy_string(entry->label, sizeof(entry->label), label);
            if (payload_size_captured) {
                entry->payload_size_captured = true;
                entry->payload_size = payload_size;
            }
            return;
        }
    }
    entry = (com_object_resource_t *)dr_global_alloc(sizeof(*entry));
    if (entry == NULL)
        return;
    memset(entry, 0, sizeof(*entry));
    entry->object = object;
    copy_string(entry->interface_name, sizeof(entry->interface_name), interface_name);
    copy_string(entry->label, sizeof(entry->label), label);
    entry->payload_size_captured = payload_size_captured;
    entry->payload_size = payload_size;
    entry->next = com_object_resources;
    com_object_resources = entry;
}

