static const char *
api_com_vtable_subsystem(const char *module_name)
{
    if (contains_ci(module_name, "dsound"))
        return "audio";
    if (contains_ci(module_name, "dinput"))
        return "input";
    if (contains_ci(module_name, "ddraw") ||
        contains_ci(module_name, "d3d") ||
        contains_ci(module_name, "dxgi"))
        return "graphics";
    return "com";
}

static void
api_com_add_method_candidate(api_com_vtable_effect_t *com_effect,
                             const char *candidate)
{
    if (com_effect == NULL || candidate == NULL || candidate[0] == '\0')
        return;
    if (com_effect->method_candidate_count >= SIDE_EFFECT_COM_METHOD_CANDIDATE_MAX) {
        com_effect->method_ambiguous = true;
        return;
    }
    com_effect->method_candidates[com_effect->method_candidate_count++] = candidate;
    com_effect->method_ambiguous = com_effect->method_candidate_count > 1;
}

static void
api_com_clear_method_candidates(api_com_vtable_effect_t *com_effect)
{
    uint i;
    if (com_effect == NULL)
        return;
    for (i = 0; i < SIDE_EFFECT_COM_METHOD_CANDIDATE_MAX; ++i)
        com_effect->method_candidates[i] = NULL;
    com_effect->method_candidate_count = 0;
    com_effect->method_ambiguous = false;
}

