static void
api_com_assign_method_metadata(api_com_vtable_effect_t *com_effect,
                               const char *module_name)
{
    const char *method_name = NULL;
    const char *semantic_kind = NULL;
    if (com_effect == NULL || !com_effect->slot_captured)
        return;
    if (com_effect->interface_known &&
        api_com_exact_method_metadata(com_effect->interface_name, com_effect->slot,
                                      &method_name, &semantic_kind)) {
        api_com_clear_method_candidates(com_effect);
        api_com_add_method_candidate(com_effect, method_name);
        com_effect->method_name = method_name;
        com_effect->method_exact = true;
        com_effect->method_ambiguous = false;
        com_effect->semantic_kind = semantic_kind;
        return;
    }
    if (com_effect->method_candidate_count > 0)
        return;
    if (contains_ci(module_name, "dsound"))
        api_com_assign_dsound_method_candidates(com_effect, com_effect->slot);
    else if (contains_ci(module_name, "dinput"))
        api_com_assign_dinput_method_candidates(com_effect, com_effect->slot);
}

static api_com_method_buffer_t *
api_com_find_method_buffer(api_com_vtable_effect_t *com_effect, const char *role,
                           uint arg_index, ptr_uint_t address)
{
    uint i;
    if (com_effect == NULL)
        return NULL;
    for (i = 0; i < com_effect->method_buffer_count; ++i) {
        api_com_method_buffer_t *buffer = &com_effect->method_buffers[i];
        if (buffer->arg_index == arg_index && buffer->address == address &&
            buffer->role != NULL && role != NULL && strcmp(buffer->role, role) == 0)
            return buffer;
    }
    return NULL;
}

