    WINCR_GUID_MATCH(IDirect3DVolume8, 0xBD7349F5u, 0x14F1u, 0x42E4u,
                     0x9Cu, 0x79u, 0x97u, 0x23u, 0x80u, 0xDBu, 0x40u,
                     0xC0u);
    WINCR_GUID_MATCH(IDirect3DSwapChain8, 0x928C088Bu, 0x76B9u, 0x4C6Bu,
                     0xA5u, 0x36u, 0xA5u, 0x90u, 0x85u, 0x38u, 0x76u,
                     0xCDu);
    WINCR_GUID_MATCH(IDirect3DSurface8, 0xB96EEBCAu, 0xB326u, 0x4EA5u,
                     0x88u, 0x2Fu, 0x2Fu, 0xF5u, 0xBAu, 0xE0u, 0x21u,
                     0xDDu);
    WINCR_GUID_MATCH(IDirect3DIndexBuffer8, 0x0E689C9Au, 0x053Du, 0x44A0u,
                     0x9Du, 0x92u, 0xDBu, 0x0Eu, 0x3Du, 0x75u, 0x0Fu,
                     0x86u);
    WINCR_GUID_MATCH(IDirect3DBaseTexture8, 0xB4211CFAu, 0x51B9u, 0x4A9Fu,
                     0xABu, 0x78u, 0xDBu, 0x99u, 0xB2u, 0xBBu, 0x67u,
                     0x8Eu);
    WINCR_GUID_MATCH(IDirect3DTexture8, 0xE4CDD575u, 0x2866u, 0x4F01u,
                     0xB1u, 0x2Eu, 0x7Eu, 0xECu, 0xE1u, 0xECu, 0x93u,
                     0x58u);
    WINCR_GUID_MATCH(IDirect3DCubeTexture8, 0x3EE5B968u, 0x2ACAu, 0x4C34u,
                     0x8Bu, 0xB5u, 0x7Eu, 0x0Cu, 0x3Du, 0x19u, 0xB7u,
                     0x50u);
