typedef struct {
    bool has_buffer;
    uint64_t size;
} ioctl_request_shape_t;

static bool
syscall_is_ioctl(int sysnum)
{
#if defined(_WIN32)
    (void)sysnum;
    return false;
#elif defined(X64)
    return sysnum == 16;
#else
    return sysnum == 54;
#endif
}

static uint64_t
linux_ioctl_encoded_size(uint64_t request)
{
    return (request >> 16) & 0x3fffull;
}

static uint64_t
linux_ioctl_encoded_dir(uint64_t request)
{
    return (request >> 30) & 0x3ull;
}

static uint64_t
linux_ifreq_size(void)
{
#if defined(X64)
    return 40;
#else
    return 32;
#endif
}

static bool
ioctl_request_shape(uint64_t request, ioctl_request_shape_t *shape)
{
    uint64_t encoded_size;
    uint64_t encoded_dir;
    if (shape == NULL)
        return false;
    memset(shape, 0, sizeof(*shape));
    encoded_size = linux_ioctl_encoded_size(request);
    encoded_dir = linux_ioctl_encoded_dir(request);
    if (encoded_size > 0 && encoded_dir != 0) {
        shape->has_buffer = true;
        shape->size = encoded_size;
        return true;
    }

    switch ((uint32_t)request) {
    case 0x5401: /* TCGETS */
    case 0x5402: /* TCSETS */
    case 0x5403: /* TCSETSW */
    case 0x5404: /* TCSETSF */
        shape->has_buffer = true;
        shape->size = 60;
        return true;
    case 0x5413: /* TIOCGWINSZ */
    case 0x5414: /* TIOCSWINSZ */
        shape->has_buffer = true;
        shape->size = 8;
        return true;
    case 0x540f: /* TIOCGPGRP */
    case 0x5410: /* TIOCSPGRP */
    case 0x541b: /* FIONREAD */
    case 0x5421: /* FIONBIO */
    case 0x5423: /* TIOCSETD */
    case 0x5424: /* TIOCGETD */
        shape->has_buffer = true;
        shape->size = 4;
        return true;
    case 0x8913: /* SIOCGIFFLAGS */
    case 0x8914: /* SIOCSIFFLAGS */
    case 0x8915: /* SIOCGIFADDR */
    case 0x8916: /* SIOCSIFADDR */
    case 0x891b: /* SIOCGIFNETMASK */
    case 0x891c: /* SIOCSIFNETMASK */
    case 0x8921: /* SIOCGIFMTU */
    case 0x8922: /* SIOCSIFMTU */
    case 0x8933: /* SIOCGIFINDEX */
        shape->has_buffer = true;
        shape->size = linux_ifreq_size();
        return true;
    default:
        return false;
    }
}

