static bool
syscall_effect_decoder_complete(const syscall_effect_t *effect)
{
    ioctl_request_shape_t shape;
    if (effect == NULL)
        return false;
    if (syscall_is_ioctl(effect->sysnum)) {
        if (effect->arg_count <= 1)
            return false;
        return ioctl_request_shape((uint64_t)effect->args[1], &shape);
    }
    return syscall_decoder_complete(effect->sysnum);
}

