static bool
read_iovec_descriptor(ptr_uint_t address, ptr_uint_t *base, uint64_t *size)
{
    reg_t base_value = 0;
    reg_t size_value = 0;
    if (base == NULL || size == NULL)
        return false;
    if (!read_reg_field(address, &base_value) ||
        !read_reg_field(address + sizeof(reg_t), &size_value))
        return false;
    *base = (ptr_uint_t)base_value;
    *size = (uint64_t)size_value;
    return true;
}

static bool
iovec_descriptor_size(uint64_t iov_count, uint64_t *size)
{
    uint64_t stride = sizeof(reg_t) * 2;
    if (size == NULL || iov_count == 0 || iov_count > UINT64_MAX / stride)
        return false;
    *size = iov_count * stride;
    return true;
}

static void
sha256_update_u64_le(sha256_ctx_t *ctx, uint64_t value)
{
    uint8_t encoded[8];
    uint i;
    for (i = 0; i < sizeof(encoded); ++i)
        encoded[i] = (uint8_t)((value >> (i * 8)) & 0xff);
    sha256_update(ctx, encoded, sizeof(encoded));
}

static bool
sha256_update_memory_range(sha256_ctx_t *ctx, ptr_uint_t address, uint64_t size)
{
    uint8_t buffer[4096];
    uint64_t offset = 0;
    ptr_uint_t pointer_max = (ptr_uint_t)~(ptr_uint_t)0;

    if (ctx == NULL)
        return false;
    if (size == 0)
        return true;
    if (address == 0)
        return false;
    while (offset < size) {
        size_t bytes_read = 0;
        uint64_t remaining = size - offset;
        size_t want = remaining > sizeof(buffer) ? sizeof(buffer) : (size_t)remaining;

        if (offset > (uint64_t)pointer_max || address > pointer_max - (ptr_uint_t)offset ||
            !dr_safe_read((void *)(address + (ptr_uint_t)offset), want, buffer,
                          &bytes_read) ||
            bytes_read != want)
            return false;
        sha256_update(ctx, buffer, bytes_read);
        offset += bytes_read;
    }
    return true;
}

static bool
sha256_update_iovec_payloads(sha256_ctx_t *ctx, ptr_uint_t iov_array,
                             uint64_t iov_count, bool include_descriptor_values)
{
    uint64_t stride = sizeof(reg_t) * 2;
    uint64_t i;
    ptr_uint_t pointer_max = (ptr_uint_t)~(ptr_uint_t)0;

    if (ctx == NULL || iov_array == 0 || iov_count == 0)
        return false;
    sha256_update_u64_le(ctx, iov_count);
    for (i = 0; i < iov_count; ++i) {
        ptr_uint_t base = 0;
        uint64_t size = 0;
        uint64_t descriptor_offset;
        ptr_uint_t descriptor;

        if (i > UINT64_MAX / stride)
            return false;
        descriptor_offset = i * stride;
        if (descriptor_offset > (uint64_t)pointer_max ||
            iov_array > pointer_max - (ptr_uint_t)descriptor_offset)
            return false;
        descriptor = iov_array + (ptr_uint_t)descriptor_offset;
        if (!read_iovec_descriptor(descriptor, &base, &size))
            return false;
        if (include_descriptor_values)
            sha256_update_u64_le(ctx, (uint64_t)base);
        sha256_update_u64_le(ctx, size);
        if (!sha256_update_memory_range(ctx, base, size))
            return false;
    }
    return true;
}

static bool
hash_iovec_payloads(ptr_uint_t iov_array, uint64_t iov_count, char hex[65])
{
    sha256_ctx_t ctx;
    uint8_t digest[SHA256_DIGEST_SIZE];

    if (hex == NULL)
        return false;
    hex[0] = '\0';
    sha256_init(&ctx);
    if (!sha256_update_iovec_payloads(&ctx, iov_array, iov_count, false))
        return false;
    sha256_final(&ctx, digest);
    sha256_digest_hex(digest, hex);
    return true;
}

typedef struct {
    ptr_uint_t name;
    uint64_t name_len;
    ptr_uint_t iov;
    uint64_t iov_len;
    ptr_uint_t control;
    uint64_t control_len;
} syscall_msghdr_fields_t;

static uint64_t
syscall_msghdr_header_size(void)
{
#if defined(_WIN32)
    return 0;
#elif defined(X64)
    return 56;
#else
    return 28;
#endif
}

static uint64_t
syscall_mmsghdr_header_size(void)
{
    return syscall_msghdr_header_size() + 8;
}

static bool
read_msghdr_descriptor(ptr_uint_t address, syscall_msghdr_fields_t *out)
{
    reg_t value = 0;
    uint32_t len32 = 0;
    if (out == NULL || address == 0)
        return false;
    memset(out, 0, sizeof(*out));
#if defined(_WIN32)
    (void)value;
    (void)len32;
    return false;
#elif defined(X64)
    if (!read_reg_field(address, &value))
        return false;
    out->name = (ptr_uint_t)value;
    if (!read_u32_field(address + 8, &len32))
        return false;
    out->name_len = len32;
    if (!read_reg_field(address + 16, &value))
        return false;
    out->iov = (ptr_uint_t)value;
    if (!read_reg_field(address + 24, &value))
        return false;
    out->iov_len = (uint64_t)value;
    if (!read_reg_field(address + 32, &value))
        return false;
    out->control = (ptr_uint_t)value;
    if (!read_reg_field(address + 40, &value))
        return false;
    out->control_len = (uint64_t)value;
    return true;
#else
    if (!read_reg_field(address, &value))
        return false;
    out->name = (ptr_uint_t)value;
    if (!read_u32_field(address + 4, &len32))
        return false;
    out->name_len = len32;
    if (!read_reg_field(address + 8, &value))
        return false;
    out->iov = (ptr_uint_t)value;
    if (!read_reg_field(address + 12, &value))
        return false;
    out->iov_len = (uint64_t)value;
    if (!read_reg_field(address + 16, &value))
        return false;
    out->control = (ptr_uint_t)value;
    if (!read_reg_field(address + 20, &value))
        return false;
    out->control_len = (uint64_t)value;
    return true;
#endif
}

static bool
mmsghdr_descriptor_size(uint64_t msg_count, uint64_t stride, uint64_t *size)
{
    if (size == NULL || msg_count == 0 || stride == 0 ||
        msg_count > UINT64_MAX / stride)
        return false;
    *size = msg_count * stride;
    return true;
}

static void
append_memory_region_ref(char **cursor, char *limit, bool known, uint64_t offset,
                         const char *kind, const char *label)
{
    append_raw(cursor, limit, ",\"region\":");
    if (!known) {
        append_raw(cursor, limit, "null");
        return;
    }
    append_raw(cursor, limit, "{\"kind\":");
    append_json_string(cursor, limit, kind == NULL ? "" : kind);
    append_raw(cursor, limit, ",\"label\":");
    append_json_string(cursor, limit, label == NULL ? "" : label);
    append_raw(cursor, limit, ",\"offset\":");
    append_u64(cursor, limit, (unsigned long long)offset);
    append_raw(cursor, limit, "}");
}

static bool
sha256_update_msghdr_payloads(sha256_ctx_t *ctx, const syscall_msghdr_fields_t *msg)
{
    if (ctx == NULL || msg == NULL)
        return false;

    sha256_update_u64_le(ctx, msg->name_len);
    if (msg->name_len > 0 && !sha256_update_memory_range(ctx, msg->name, msg->name_len))
        return false;

    sha256_update_u64_le(ctx, msg->control_len);
    if (msg->control_len > 0 &&
        !sha256_update_memory_range(ctx, msg->control, msg->control_len))
        return false;

    sha256_update_u64_le(ctx, msg->iov_len);
    if (msg->iov_len > 0 &&
        !sha256_update_iovec_payloads(ctx, msg->iov, msg->iov_len, true))
        return false;

    return true;
}

static bool
hash_mmsghdr_payloads(ptr_uint_t msg_array, uint64_t msg_count, uint64_t stride,
                      char hex[65])
{
    sha256_ctx_t ctx;
    uint8_t digest[SHA256_DIGEST_SIZE];
    uint64_t i;
    ptr_uint_t pointer_max = (ptr_uint_t)~(ptr_uint_t)0;

    if (hex == NULL)
        return false;
    hex[0] = '\0';
    if (msg_array == 0 || msg_count == 0 || stride == 0)
        return false;

    sha256_init(&ctx);
    sha256_update_u64_le(&ctx, msg_count);
    for (i = 0; i < msg_count; ++i) {
        syscall_msghdr_fields_t msg;
        uint64_t descriptor_offset;
        ptr_uint_t msg_address;

        if (i > UINT64_MAX / stride)
            return false;
        descriptor_offset = i * stride;
        if (descriptor_offset > (uint64_t)pointer_max ||
            msg_array > pointer_max - (ptr_uint_t)descriptor_offset)
            return false;
        msg_address = msg_array + (ptr_uint_t)descriptor_offset;
        if (!read_msghdr_descriptor(msg_address, &msg))
            return false;
        if (!sha256_update_msghdr_payloads(&ctx, &msg))
            return false;
    }

    sha256_final(&ctx, digest);
    sha256_digest_hex(digest, hex);
    return true;
}

static bool
syscall_sample_covered_by_aggregate(const pending_syscall_effect_t *pending,
                                    const char *source, uint arg_index,
                                    bool message_index_captured,
                                    uint message_index)
{
    uint i;
    if (pending == NULL || source == NULL)
        return false;
    for (i = 0; i < pending->aggregate_count; ++i) {
        const syscall_aggregate_effect_t *aggregate = &pending->aggregates[i];
        if (aggregate->arg_index != arg_index || aggregate->source == NULL)
            continue;
        if (strcmp(aggregate->source, "mmsghdr_array") == 0 &&
            message_index_captured &&
            (strcmp(source, "mmsghdr") == 0 ||
             strcmp(source, "msghdr_name") == 0 ||
             strcmp(source, "msghdr_control") == 0 ||
             strcmp(source, "msghdr_iovec_data") == 0))
            return true;
        if (strcmp(aggregate->source, "iovec_array") == 0 &&
            strcmp(source, "iovec_data") == 0 && !aggregate->message_index_captured)
            return true;
        if (strcmp(aggregate->source, "iovec_array") == 0 &&
            strcmp(source, "msghdr_iovec_data") == 0 &&
            aggregate->message_index_captured == message_index_captured &&
            (!message_index_captured || aggregate->message_index == message_index))
            return true;
    }
    return false;
}

static bool
record_syscall_buffer_aggregate_entry(pending_syscall_effect_t *pending,
                                      uint arg_index, ptr_uint_t address,
                                      uint64_t size, bool truncated,
                                      const char *source,
                                      bool iov_index_captured,
                                      uint iov_index,
                                      bool message_index_captured,
                                      uint message_index,
                                      const char before_sha256[65],
                                      bool before_sha256_ok)
{
    syscall_buffer_aggregate_effect_t *aggregate;
    syscall_buffer_aggregate_entry_t *entry;
    if (pending == NULL)
        return false;
    aggregate = &pending->buffer_aggregate;
    if (aggregate->entry_count >= SIDE_EFFECT_SYSCALL_BUFFER_AGGREGATE_MAX)
        return false;
    if (!aggregate->active)
        aggregate->complete = true;
    aggregate->active = true;
    entry = &aggregate->entries[aggregate->entry_count++];
    memset(entry, 0, sizeof(*entry));
    entry->source = source == NULL ? "argument" : source;
    entry->arg_index = arg_index;
    entry->iov_index_captured = iov_index_captured;
    entry->iov_index = iov_index;
    entry->message_index_captured = message_index_captured;
    entry->message_index = message_index;
    entry->address = address;
    entry->size = size;
    entry->truncated = truncated;
    entry->before_sha256_ok = before_sha256_ok;
    copy_string(entry->before_sha256, sizeof(entry->before_sha256), before_sha256);
    if (!before_sha256_ok)
        aggregate->complete = false;
    return true;
}

static void
syscall_buffer_aggregate_update_digest(sha256_ctx_t *ctx, const char digest[65],
                                       bool digest_ok, bool *complete)
{
    if (!digest_ok || digest == NULL || digest[0] == '\0') {
        if (complete != NULL)
            *complete = false;
        sha256_update_u64_le(ctx, 0);
        return;
    }
    sha256_update_u64_le(ctx, 1);
    sha256_update(ctx, (const uint8_t *)digest, 64);
}

static void
finalize_syscall_buffer_aggregate(syscall_effect_t *effect)
{
    syscall_buffer_aggregate_effect_t *aggregate;
    sha256_ctx_t ctx;
    uint8_t digest[SHA256_DIGEST_SIZE];
    uint i;

    if (effect == NULL)
        return;
    aggregate = &effect->buffer_aggregate;
    if (!aggregate->active)
        return;

    sha256_init(&ctx);
    sha256_update_u64_le(&ctx, aggregate->entry_count);
    for (i = 0; i < aggregate->entry_count; ++i) {
        syscall_buffer_aggregate_entry_t *entry = &aggregate->entries[i];
        sha256_update_string_field(&ctx, entry->source);
        sha256_update_u64_le(&ctx, entry->arg_index);
        sha256_update_u64_le(&ctx, entry->iov_index_captured ? 1 : 0);
        sha256_update_u64_le(&ctx, entry->iov_index);
        sha256_update_u64_le(&ctx, entry->message_index_captured ? 1 : 0);
        sha256_update_u64_le(&ctx, entry->message_index);
        sha256_update_u64_le(&ctx, (uint64_t)entry->address);
        sha256_update_u64_le(&ctx, entry->size);
        sha256_update_u64_le(&ctx, entry->truncated ? 1 : 0);
        syscall_buffer_aggregate_update_digest(&ctx, entry->before_sha256,
                                               entry->before_sha256_ok,
                                               &aggregate->complete);
        entry->after_sha256_ok =
            read_memory_sha256(entry->address, entry->size, entry->after_sha256);
        syscall_buffer_aggregate_update_digest(&ctx, entry->after_sha256,
                                               entry->after_sha256_ok,
                                               &aggregate->complete);
    }

    if (!aggregate->complete || aggregate->entry_count == 0) {
        aggregate->sha256_ok = false;
        aggregate->sha256[0] = '\0';
        return;
    }
    sha256_final(&ctx, digest);
    sha256_digest_hex(digest, aggregate->sha256);
    aggregate->sha256_ok = true;
}

static void
capture_syscall_buffer_sample_for_message(pending_syscall_effect_t *pending,
                                          uint arg_index, ptr_uint_t address,
                                          uint64_t size, bool truncated,
                                          const char *source,
                                          bool iov_index_captured,
                                          uint iov_index,
                                          bool message_index_captured,
                                          uint message_index)
{
    syscall_buffer_effect_t *buffer;
    uint before_len = 0;
    uint8_t before[SIDE_EFFECT_VALUE_MAX];
    bool before_sha256_ok;
    char before_sha256[65];
    uint sample_size;
    bool before_ok;
    if (pending == NULL || size == 0)
        return;
    sample_size = size > SIDE_EFFECT_VALUE_MAX ? SIDE_EFFECT_VALUE_MAX : (uint)size;
    before_ok = read_memory_sample(address, sample_size, before, &before_len);
    before_sha256_ok = read_memory_sha256(address, size, before_sha256);
    if (pending->buffer_count >= SIDE_EFFECT_SYSCALL_BUFFER_MAX) {
        if (!syscall_sample_covered_by_aggregate(pending, source, arg_index,
                                                 message_index_captured,
                                                 message_index) &&
            !record_syscall_buffer_aggregate_entry(
                pending, arg_index, address, size, truncated, source,
                iov_index_captured, iov_index, message_index_captured,
                message_index, before_sha256, before_sha256_ok))
            ++pending->buffer_dropped;
        return;
    }
    buffer = &pending->buffers[pending->buffer_count++];
    memset(buffer, 0, sizeof(*buffer));
    buffer->source = source == NULL ? "argument" : source;
    buffer->arg_index = arg_index;
    buffer->iov_index_captured = iov_index_captured;
    buffer->iov_index = iov_index;
    buffer->message_index_captured = message_index_captured;
    buffer->message_index = message_index;
    buffer->address = address;
    buffer->size = size;
    buffer->before_len = before_len;
    memcpy(buffer->before, before, sizeof(buffer->before));
    buffer->before_ok = before_ok;
    buffer->before_sha256_ok = before_sha256_ok;
    copy_string(buffer->before_sha256, sizeof(buffer->before_sha256), before_sha256);
    buffer->truncated = truncated;
}

static void
capture_syscall_buffer_sample(pending_syscall_effect_t *pending, uint arg_index,
                              ptr_uint_t address, uint64_t size, bool truncated,
                              const char *source, bool iov_index_captured,
                              uint iov_index)
{
    capture_syscall_buffer_sample_for_message(pending, arg_index, address, size,
                                              truncated, source,
                                              iov_index_captured, iov_index,
                                              false, 0);
}

static bool
capture_syscall_iovec_aggregate(pending_syscall_effect_t *pending, uint arg_index,
                                ptr_uint_t iov_array, uint64_t iov_count,
                                bool message_index_captured, uint message_index)
{
    syscall_aggregate_effect_t *aggregate;
    uint64_t descriptor_size = 0;

    if (pending == NULL || iov_array == 0 || iov_count == 0)
        return false;
    if (pending->aggregate_count >= SIDE_EFFECT_SYSCALL_AGGREGATE_MAX) {
        ++pending->aggregate_dropped;
        return false;
    }

    aggregate = &pending->aggregates[pending->aggregate_count++];
    memset(aggregate, 0, sizeof(*aggregate));
    aggregate->source = "iovec_array";
    aggregate->arg_index = arg_index;
    aggregate->message_index_captured = message_index_captured;
    aggregate->message_index = message_index;
    aggregate->element_count = iov_count;
    aggregate->descriptor_address = iov_array;

    if (iovec_descriptor_size(iov_count, &descriptor_size)) {
        aggregate->descriptor_size = descriptor_size;
        aggregate->descriptor_sha256_ok =
            read_memory_sha256(iov_array, descriptor_size, aggregate->descriptor_sha256);
    }
    aggregate->before_sha256_ok =
        hash_iovec_payloads(iov_array, iov_count, aggregate->before_sha256);
    return true;
}

static bool
capture_syscall_mmsghdr_aggregate(pending_syscall_effect_t *pending, uint arg_index,
                                  ptr_uint_t msg_array, uint64_t msg_count,
                                  uint64_t stride)
{
    syscall_aggregate_effect_t *aggregate;
    uint64_t descriptor_size = 0;

    if (pending == NULL || msg_array == 0 || msg_count == 0 || stride == 0)
        return false;
    if (pending->aggregate_count >= SIDE_EFFECT_SYSCALL_AGGREGATE_MAX) {
        ++pending->aggregate_dropped;
        return false;
    }

    aggregate = &pending->aggregates[pending->aggregate_count++];
    memset(aggregate, 0, sizeof(*aggregate));
    aggregate->source = "mmsghdr_array";
    aggregate->arg_index = arg_index;
    aggregate->element_count = msg_count;
    aggregate->descriptor_address = msg_array;

    if (mmsghdr_descriptor_size(msg_count, stride, &descriptor_size)) {
        aggregate->descriptor_size = descriptor_size;
        aggregate->descriptor_sha256_ok =
            read_memory_sha256(msg_array, descriptor_size, aggregate->descriptor_sha256);
    }
    aggregate->before_sha256_ok =
        hash_mmsghdr_payloads(msg_array, msg_count, stride, aggregate->before_sha256);
    return true;
}

static bool
capture_syscall_ioctl_buffer(pending_syscall_effect_t *pending)
{
    ioctl_request_shape_t shape;
    ptr_uint_t address;
    if (pending == NULL || !syscall_is_ioctl(pending->sysnum))
        return false;
    if (pending->arg_count <= 1 ||
        !ioctl_request_shape((uint64_t)pending->args[1], &shape))
        return false;
    if (!shape.has_buffer)
        return true;
    if (pending->arg_count <= 2) {
        ++pending->buffer_dropped;
        return true;
    }
    address = (ptr_uint_t)pending->args[2];
    if (address == 0) {
        ++pending->buffer_dropped;
        return true;
    }
    capture_syscall_buffer_sample(pending, 2, address, shape.size,
                                  shape.size > SIDE_EFFECT_VALUE_MAX,
                                  "ioctl_data", false, 0);
    return true;
}

static bool
capture_syscall_msghdr_fields_buffers(pending_syscall_effect_t *pending,
                                      uint msg_arg_index,
                                      ptr_uint_t msg_address,
                                      uint64_t envelope_size,
                                      const char *envelope_source,
                                      bool message_index_captured,
                                      uint message_index)
{
    syscall_msghdr_fields_t msg;
    uint64_t capture_count;
    uint64_t i;
    if (pending == NULL)
        return false;
    if (msg_address == 0) {
        ++pending->buffer_dropped;
        return true;
    }
    capture_syscall_buffer_sample_for_message(pending, msg_arg_index,
                                              msg_address, envelope_size,
                                              false, envelope_source, false, 0,
                                              message_index_captured,
                                              message_index);
    if (!read_msghdr_descriptor(msg_address, &msg)) {
        ++pending->buffer_dropped;
        return true;
    }
    if (msg.name_len > 0) {
        if (msg.name == 0) {
            ++pending->buffer_dropped;
        } else {
            capture_syscall_buffer_sample_for_message(
                pending, msg_arg_index, msg.name, msg.name_len,
                msg.name_len > SIDE_EFFECT_VALUE_MAX, "msghdr_name", false, 0,
                message_index_captured, message_index);
        }
    }
    if (msg.control_len > 0) {
        if (msg.control == 0) {
            ++pending->buffer_dropped;
        } else {
            capture_syscall_buffer_sample_for_message(
                pending, msg_arg_index, msg.control, msg.control_len,
                msg.control_len > SIDE_EFFECT_VALUE_MAX, "msghdr_control",
                false, 0, message_index_captured, message_index);
        }
    }
    if (msg.iov_len == 0)
        return true;
    if (msg.iov == 0) {
        ++pending->buffer_dropped;
        return true;
    }
    capture_count = msg.iov_len;
    if (capture_count > SIDE_EFFECT_IOV_MAX) {
        capture_syscall_iovec_aggregate(pending, msg_arg_index, msg.iov, msg.iov_len,
                                        message_index_captured, message_index);
        capture_count = SIDE_EFFECT_IOV_MAX;
    }
    for (i = 0; i < capture_count; ++i) {
        ptr_uint_t base = 0;
        uint64_t size = 0;
        ptr_uint_t descriptor = msg.iov + (ptr_uint_t)(i * sizeof(reg_t) * 2);
        if (!read_iovec_descriptor(descriptor, &base, &size)) {
            ++pending->buffer_dropped;
            continue;
        }
        if (size == 0)
            continue;
        capture_syscall_buffer_sample_for_message(
            pending, msg_arg_index, base, size, size > SIDE_EFFECT_VALUE_MAX,
            "msghdr_iovec_data", true, (uint)i, message_index_captured,
            message_index);
    }
    return true;
}

static bool
capture_syscall_msghdr_buffers(pending_syscall_effect_t *pending)
{
    uint msg_arg_index = 0;
    ptr_uint_t msg_address;
    if (pending == NULL || !syscall_msghdr_arg_index(pending->sysnum, &msg_arg_index))
        return false;
    if (msg_arg_index >= pending->arg_count) {
        ++pending->buffer_dropped;
        return true;
    }
    msg_address = (ptr_uint_t)pending->args[msg_arg_index];
    return capture_syscall_msghdr_fields_buffers(
        pending, msg_arg_index, msg_address, syscall_msghdr_header_size(),
        "msghdr", false, 0);
}

static bool
capture_syscall_mmsghdr_buffers(pending_syscall_effect_t *pending)
{
    uint msg_arg_index = 0;
    uint msg_count_index = 0;
    uint64_t msg_count;
    uint64_t capture_count;
    uint64_t i;
    ptr_uint_t msg_array;
    uint64_t stride = syscall_mmsghdr_header_size();
    if (pending == NULL ||
        !syscall_mmsghdr_args(pending->sysnum, &msg_arg_index, &msg_count_index))
        return false;
    if (msg_arg_index >= pending->arg_count || msg_count_index >= pending->arg_count) {
        ++pending->buffer_dropped;
        return true;
    }
    msg_array = (ptr_uint_t)pending->args[msg_arg_index];
    msg_count = (uint64_t)pending->args[msg_count_index];
    if (msg_count == 0)
        return true;
    if (msg_array == 0) {
        ++pending->buffer_dropped;
        return true;
    }
    capture_count = msg_count;
    if (capture_count > SIDE_EFFECT_MMSG_MAX) {
        capture_syscall_mmsghdr_aggregate(pending, msg_arg_index, msg_array, msg_count,
                                          stride);
        capture_count = SIDE_EFFECT_MMSG_MAX;
    }
    for (i = 0; i < capture_count; ++i) {
        ptr_uint_t msg_address = msg_array + (ptr_uint_t)(i * stride);
        capture_syscall_msghdr_fields_buffers(pending, msg_arg_index, msg_address,
                                              stride, "mmsghdr", true, (uint)i);
    }
    return true;
}

static bool
capture_syscall_iovec_buffers(pending_syscall_effect_t *pending)
{
    uint iov_arg_index = 0;
    uint iov_count_index = 0;
    uint64_t iov_count;
    uint64_t capture_count;
    uint64_t i;
    ptr_uint_t iov_array;
    if (pending == NULL ||
        !syscall_iovec_args(pending->sysnum, &iov_arg_index, &iov_count_index))
        return false;
    if (iov_arg_index >= pending->arg_count || iov_count_index >= pending->arg_count) {
        ++pending->buffer_dropped;
        return true;
    }
    iov_array = (ptr_uint_t)pending->args[iov_arg_index];
    iov_count = (uint64_t)pending->args[iov_count_index];
    if (iov_count == 0)
        return true;
    if (iov_array == 0) {
        ++pending->buffer_dropped;
        return true;
    }
    capture_count = iov_count;
    if (capture_count > SIDE_EFFECT_IOV_MAX) {
        capture_syscall_iovec_aggregate(pending, iov_arg_index, iov_array, iov_count,
                                        false, 0);
        capture_count = SIDE_EFFECT_IOV_MAX;
    }
    for (i = 0; i < capture_count; ++i) {
        ptr_uint_t base = 0;
        uint64_t size = 0;
        ptr_uint_t descriptor = iov_array + (ptr_uint_t)(i * sizeof(reg_t) * 2);
        if (!read_iovec_descriptor(descriptor, &base, &size)) {
            ++pending->buffer_dropped;
            continue;
        }
        if (size == 0)
            continue;
        capture_syscall_buffer_sample(pending, iov_arg_index, base, size,
                                      size > SIDE_EFFECT_VALUE_MAX,
                                      "iovec_data", true, (uint)i);
    }
    return true;
}

static void
append_memory_reads(char **cursor, char *limit, const block_state_thread_t *effects)
{
    uint i;
    append_raw(cursor, limit, "\"memory_reads\":[");
    for (i = 0; i < effects->memory_read_count; ++i) {
        const memory_read_effect_t *effect = &effects->memory_reads[i];
        if (i > 0)
            append_raw(cursor, limit, ",");
        append_raw(cursor, limit, "{\"instr_rva\":");
        append_u64(cursor, limit, (unsigned long long)effect->instr_rva);
        append_raw(cursor, limit, ",\"address\":");
        append_u64(cursor, limit, (unsigned long long)effect->address);
        append_raw(cursor, limit, ",\"size\":");
        append_u64(cursor, limit, (unsigned long long)effect->size);
        append_memory_region_ref(cursor, limit, effect->region_known,
                                 effect->region_offset, effect->region_kind,
                                 effect->region_label);
        append_raw(cursor, limit, ",\"value\":");
        append_hex_bytes(cursor, limit, effect->value, effect->value_len);
        append_raw(cursor, limit, ",\"value_sha256\":");
        append_json_string(cursor, limit,
                           effect->value_sha256_ok ? effect->value_sha256 : "");
        append_raw(cursor, limit, ",\"value_sha256_ok\":");
        append_bool(cursor, limit, effect->value_sha256_ok);
        append_raw(cursor, limit, ",\"read_ok\":");
        append_bool(cursor, limit, effect->read_ok);
        append_raw(cursor, limit, ",\"truncated\":");
        append_bool(cursor, limit, effect->truncated);
        append_raw(cursor, limit, "}");
    }
    append_raw(cursor, limit, "]");
}

static void
append_memory_writes(char **cursor, char *limit, const block_state_thread_t *effects)
{
    uint i;
    append_raw(cursor, limit, "\"memory_writes\":[");
    for (i = 0; i < effects->memory_write_count; ++i) {
        const memory_write_effect_t *effect = &effects->memory_writes[i];
        if (i > 0)
            append_raw(cursor, limit, ",");
        append_raw(cursor, limit, "{\"instr_rva\":");
        append_u64(cursor, limit, (unsigned long long)effect->instr_rva);
        append_raw(cursor, limit, ",\"address\":");
        append_u64(cursor, limit, (unsigned long long)effect->address);
        append_raw(cursor, limit, ",\"size\":");
        append_u64(cursor, limit, (unsigned long long)effect->size);
        append_memory_region_ref(cursor, limit, effect->region_known,
                                 effect->region_offset, effect->region_kind,
                                 effect->region_label);
        append_raw(cursor, limit, ",\"before\":");
        append_hex_bytes(cursor, limit, effect->before, effect->before_len);
        append_raw(cursor, limit, ",\"before_sha256\":");
        append_json_string(cursor, limit,
                           effect->before_sha256_ok ? effect->before_sha256 : "");
        append_raw(cursor, limit, ",\"before_sha256_ok\":");
        append_bool(cursor, limit, effect->before_sha256_ok);
        append_raw(cursor, limit, ",\"after\":");
        append_hex_bytes(cursor, limit, effect->after, effect->after_len);
        append_raw(cursor, limit, ",\"after_sha256\":");
        append_json_string(cursor, limit,
                           effect->after_sha256_ok ? effect->after_sha256 : "");
        append_raw(cursor, limit, ",\"after_sha256_ok\":");
        append_bool(cursor, limit, effect->after_sha256_ok);
        append_raw(cursor, limit, ",\"before_ok\":");
        append_bool(cursor, limit, effect->before_ok);
        append_raw(cursor, limit, ",\"after_ok\":");
        append_bool(cursor, limit, effect->after_ok);
        append_raw(cursor, limit, ",\"truncated\":");
        append_bool(cursor, limit, effect->truncated);
        append_raw(cursor, limit, "}");
    }
    append_raw(cursor, limit, "]");
}

static void
append_memory_aggregate_entry(char **cursor, char *limit, const char *name,
                              const memory_effect_aggregate_t *aggregate)
{
    char digest[65];
    bool digest_ok = memory_effect_aggregate_digest(aggregate, digest);

    append_raw(cursor, limit, "\"");
    append_raw(cursor, limit, name);
    append_raw(cursor, limit, "\":{\"count\":");
    append_u64(cursor, limit,
               (unsigned long long)(aggregate != NULL && aggregate->active ?
                                    aggregate->count : 0));
    append_raw(cursor, limit, ",\"sha256\":");
    append_json_string(cursor, limit, digest_ok ? digest : "");
    append_raw(cursor, limit, ",\"sha256_ok\":");
    append_bool(cursor, limit, digest_ok);
    append_raw(cursor, limit, "}");
}

static void
append_memory_aggregates(char **cursor, char *limit, const block_state_thread_t *effects)
{
    append_raw(cursor, limit, "\"memory_aggregates\":{");
    append_memory_aggregate_entry(cursor, limit, "reads",
                                  effects == NULL ? NULL : &effects->memory_read_aggregate);
    append_raw(cursor, limit, ",");
    append_memory_aggregate_entry(cursor, limit, "writes",
                                  effects == NULL ? NULL : &effects->memory_write_aggregate);
    append_raw(cursor, limit, "}");
}

static int64_t
api_arg_i32(const api_call_effect_t *effect, uint index)
{
    if (effect == NULL || index >= effect->arg_count)
        return 0;
    return (int64_t)(int32_t)(uint32_t)effect->args[index];
}

static void
append_api_framebuffer_resource(char **cursor, char *limit,
                                const api_resource_ref_t *ref)
{
    if (ref == NULL) {
        append_raw(cursor, limit, "null");
        return;
    }
    append_raw(cursor, limit, "{\"arg_index\":");
    append_u64(cursor, limit, (unsigned long long)ref->arg_index);
    append_raw(cursor, limit, ",\"role\":");
    append_json_string(cursor, limit, ref->role);
    append_raw(cursor, limit, ",\"handle\":");
    if (ref->handle_captured)
        append_u64(cursor, limit, (unsigned long long)ref->handle);
    else
        append_raw(cursor, limit, "null");
    append_raw(cursor, limit, ",\"known\":");
    append_bool(cursor, limit, ref->resource_known);
    append_raw(cursor, limit, ",\"kind\":");
    append_json_string(cursor, limit, ref->resource_known ? ref->kind : "");
    append_raw(cursor, limit, ",\"label\":");
    append_json_string(cursor, limit, ref->resource_known ? ref->label : "");
    append_raw(cursor, limit, "}");
}

static void
append_api_framebuffer_rect(char **cursor, char *limit,
                            const api_call_effect_t *effect, bool captured,
                            uint x_arg, uint y_arg, uint width_arg, uint height_arg)
{
    if (!captured || effect == NULL || x_arg >= effect->arg_count ||
        y_arg >= effect->arg_count || width_arg >= effect->arg_count ||
        height_arg >= effect->arg_count) {
        append_raw(cursor, limit, "null");
        return;
    }
    append_raw(cursor, limit, "{\"x\":");
    append_i64(cursor, limit, api_arg_i32(effect, x_arg));
    append_raw(cursor, limit, ",\"y\":");
    append_i64(cursor, limit, api_arg_i32(effect, y_arg));
    append_raw(cursor, limit, ",\"width\":");
    append_i64(cursor, limit, api_arg_i32(effect, width_arg));
    append_raw(cursor, limit, ",\"height\":");
    append_i64(cursor, limit, api_arg_i32(effect, height_arg));
    append_raw(cursor, limit, "}");
}

static void
append_api_framebuffer_raster_op(char **cursor, char *limit,
                                 const api_call_effect_t *effect, bool captured,
                                 uint arg_index)
{
    if (!captured || effect == NULL || arg_index >= effect->arg_count) {
        append_raw(cursor, limit, "null");
        return;
    }
    append_u64(cursor, limit,
               (unsigned long long)(uint32_t)effect->args[arg_index]);
}

static void
append_api_framebuffer_payload(char **cursor, char *limit,
                               const api_call_effect_t *effect)
{
    append_raw(cursor, limit, "{\"kind\":");
    if (string_eq_ci(effect->callee_symbol, "SwapBuffers")) {
        append_json_string(cursor, limit, "opengl_back_buffer");
        append_raw(cursor, limit, ",\"source_target_arg\":null,"
                   "\"bits_arg\":null,\"bits_digest_captured\":false,"
                   "\"bitmap_info_arg\":null,\"bitmap_info_digest_captured\":false}");
        return;
    }
    if (string_eq_ci(effect->callee_symbol, "PatBlt")) {
        append_json_string(cursor, limit, "raster_pattern");
        append_raw(cursor, limit, ",\"source_target_arg\":null,"
                   "\"bits_arg\":null,\"bits_digest_captured\":false,"
                   "\"bitmap_info_arg\":null,\"bitmap_info_digest_captured\":false}");
        return;
    }
    if (string_eq_ci(effect->callee_symbol, "SetDIBitsToDevice") ||
        string_eq_ci(effect->callee_symbol, "StretchDIBits")) {
        append_json_string(cursor, limit, "dib_argument");
        append_raw(cursor, limit, ",\"source_target_arg\":null,\"bits_arg\":9,"
                   "\"bits_digest_captured\":");
        append_bool(cursor, limit, api_has_complete_buffer_digest_arg(effect, 9));
        append_raw(cursor, limit, ",\"bitmap_info_arg\":10,"
                   "\"bitmap_info_digest_captured\":");
        append_bool(cursor, limit, api_has_complete_buffer_digest_arg(effect, 10));
        append_raw(cursor, limit, "}");
        return;
    }
    append_json_string(cursor, limit, "source_dc");
    append_raw(cursor, limit, ",\"source_target_arg\":5,"
               "\"bits_arg\":null,\"bits_digest_captured\":false,"
               "\"bitmap_info_arg\":null,\"bitmap_info_digest_captured\":false}");
}

static void
append_api_framebuffer_effect(char **cursor, char *limit,
                              const api_call_effect_t *effect)
{
    const api_resource_ref_t *dest;
    const api_resource_ref_t *src = NULL;
    bool has_dest_rect = false;
    bool has_src_rect = false;
    bool has_raster_op = false;
    uint dest_x = 0;
    uint dest_y = 0;
    uint dest_width = 0;
    uint dest_height = 0;
    uint src_x = 0;
    uint src_y = 0;
    uint src_width = 0;
    uint src_height = 0;
    uint raster_op = 0;

    if (effect == NULL || !api_has_framebuffer_effect(effect->callee_symbol)) {
        append_raw(cursor, limit, "null");
        return;
    }

    dest = api_find_resource_ref_by_arg(effect, 0);
    if (string_eq_ci(effect->callee_symbol, "BitBlt")) {
        src = api_find_resource_ref_by_arg(effect, 5);
        has_dest_rect = effect->arg_count >= 5;
        has_src_rect = effect->arg_count >= 8;
        has_raster_op = effect->arg_count >= 9;
        dest_x = 1;
        dest_y = 2;
        dest_width = 3;
        dest_height = 4;
        src_x = 6;
        src_y = 7;
        src_width = 3;
        src_height = 4;
        raster_op = 8;
    } else if (string_eq_ci(effect->callee_symbol, "StretchBlt")) {
        src = api_find_resource_ref_by_arg(effect, 5);
        has_dest_rect = effect->arg_count >= 5;
        has_src_rect = effect->arg_count >= 10;
        has_raster_op = effect->arg_count >= 11;
        dest_x = 1;
        dest_y = 2;
        dest_width = 3;
        dest_height = 4;
        src_x = 6;
        src_y = 7;
        src_width = 8;
        src_height = 9;
        raster_op = 10;
    } else if (string_eq_ci(effect->callee_symbol, "PatBlt")) {
        has_dest_rect = effect->arg_count >= 5;
        has_raster_op = effect->arg_count >= 6;
        dest_x = 1;
        dest_y = 2;
        dest_width = 3;
        dest_height = 4;
        raster_op = 5;
    } else if (string_eq_ci(effect->callee_symbol, "SetDIBitsToDevice")) {
        has_dest_rect = effect->arg_count >= 5;
        has_src_rect = effect->arg_count >= 9;
        dest_x = 1;
        dest_y = 2;
        dest_width = 3;
        dest_height = 4;
        src_x = 5;
        src_y = 6;
        src_width = 3;
        src_height = 8;
    } else if (string_eq_ci(effect->callee_symbol, "StretchDIBits")) {
        has_dest_rect = effect->arg_count >= 5;
        has_src_rect = effect->arg_count >= 9;
        has_raster_op = effect->arg_count >= 13;
        dest_x = 1;
        dest_y = 2;
        dest_width = 3;
        dest_height = 4;
        src_x = 5;
        src_y = 6;
        src_width = 7;
        src_height = 8;
        raster_op = 12;
    }

    append_raw(cursor, limit, "{\"captured\":");
    append_bool(cursor, limit, api_framebuffer_effect_complete(effect));
    append_raw(cursor, limit, ",\"operation\":");
    append_json_string(cursor, limit, api_drawing_operation(effect->callee_symbol));
    append_raw(cursor, limit, ",\"presentation_kind\":");
    if (string_eq_ci(effect->callee_symbol, "SwapBuffers"))
        append_json_string(cursor, limit, "opengl_swap");
    else if (string_eq_ci(effect->callee_symbol, "BitBlt") ||
             string_eq_ci(effect->callee_symbol, "StretchBlt"))
        append_json_string(cursor, limit, "dc_blit");
    else if (string_eq_ci(effect->callee_symbol, "PatBlt"))
        append_json_string(cursor, limit, "dc_raster_fill");
    else
        append_json_string(cursor, limit, "dib_to_dc");
    append_raw(cursor, limit, ",\"destination\":{\"target\":");
    append_api_framebuffer_resource(cursor, limit, dest);
    append_raw(cursor, limit, ",\"rect\":");
    append_api_framebuffer_rect(cursor, limit, effect, has_dest_rect,
                                dest_x, dest_y, dest_width, dest_height);
    append_raw(cursor, limit, "},\"source\":{\"target\":");
    append_api_framebuffer_resource(cursor, limit, src);
    append_raw(cursor, limit, ",\"rect\":");
    append_api_framebuffer_rect(cursor, limit, effect, has_src_rect,
                                src_x, src_y, src_width, src_height);
    append_raw(cursor, limit, "},\"raster_op\":");
    append_api_framebuffer_raster_op(cursor, limit, effect, has_raster_op, raster_op);
    append_raw(cursor, limit, ",\"payload\":");
    append_api_framebuffer_payload(cursor, limit, effect);
    append_raw(cursor, limit, "}");
}

static void
append_api_draw_effect(char **cursor, char *limit, const api_call_effect_t *effect)
{
    uint i;
    const api_resource_ref_t *target = NULL;
    append_raw(cursor, limit, "\"draw_effect\":");
    if (effect == NULL || !api_has_drawing_effect(effect->callee_symbol)) {
        append_raw(cursor, limit, "null");
        return;
    }
    for (i = 0; i < effect->resource_ref_count; ++i) {
        if (string_eq_ci(effect->resource_refs[i].role, "hdc") ||
            string_eq_ci(effect->resource_refs[i].role, "dest_hdc")) {
            target = &effect->resource_refs[i];
            break;
        }
    }
    append_raw(cursor, limit, "{\"captured\":");
    append_bool(cursor, limit, api_drawing_effect_complete(effect));
    append_raw(cursor, limit, ",\"succeeded\":");
    append_bool(cursor, limit, api_return_succeeded(effect));
    append_raw(cursor, limit, ",\"operation\":");
    append_json_string(cursor, limit, api_drawing_operation(effect->callee_symbol));
    append_raw(cursor, limit, ",\"target\":");
    if (target != NULL) {
        append_raw(cursor, limit, "{\"handle\":");
        if (target->handle_captured)
            append_u64(cursor, limit, (unsigned long long)target->handle);
        else
            append_raw(cursor, limit, "null");
        append_raw(cursor, limit, ",\"known\":");
        append_bool(cursor, limit, target->resource_known);
        append_raw(cursor, limit, ",\"kind\":");
        append_json_string(cursor, limit, target->resource_known ? target->kind : "");
        append_raw(cursor, limit, ",\"label\":");
        append_json_string(cursor, limit, target->resource_known ? target->label : "");
        append_raw(cursor, limit, "}");
    } else {
        append_raw(cursor, limit, "null");
    }
    append_raw(cursor, limit, ",\"arguments\":[");
    for (i = 0; i < effect->arg_count; ++i) {
        if (i > 0)
            append_raw(cursor, limit, ",");
        append_u64(cursor, limit, (unsigned long long)effect->args[i]);
    }
    append_raw(cursor, limit, "],\"framebuffer_effect\":");
    append_api_framebuffer_effect(cursor, limit, effect);
    append_raw(cursor, limit, "}");
}

