    append_json_string(cursor, limit,
                       com_effect->subsystem == NULL ? "" : com_effect->subsystem);
    append_raw(cursor, limit, ",\"semantic_kind\":");
    append_json_string(cursor, limit,
                       com_effect->semantic_kind == NULL ? "" :
                           com_effect->semantic_kind);
    append_raw(cursor, limit, ",\"method_candidates\":[");
    for (i = 0; i < com_effect->method_candidate_count; ++i) {
        if (i > 0)
            append_raw(cursor, limit, ",");
        append_json_string(cursor, limit, com_effect->method_candidates[i]);
    }
    append_raw(cursor, limit, "],\"method_ambiguous\":");
    append_bool(cursor, limit, com_effect->method_ambiguous);
    append_raw(cursor, limit, ",\"interface_captured\":");
    append_bool(cursor, limit, com_effect->interface_captured);
    append_raw(cursor, limit, ",\"interface_known\":");
    append_bool(cursor, limit, com_effect->interface_known);
    append_raw(cursor, limit, ",\"interface_name\":");
    append_json_string(cursor, limit,
                       com_effect->interface_known ? com_effect->interface_name : "");
    append_raw(cursor, limit, ",\"interface_label\":");
    append_json_string(cursor, limit,
                       com_effect->interface_known ? com_effect->interface_label : "");
    append_raw(cursor, limit, ",\"method_name\":");
