static void
sha256_update_string_field(sha256_ctx_t *ctx, const char *value)
{
    size_t len = value == NULL ? 0 : strlen(value);
    sha256_update_u64_le(ctx, (uint64_t)len);
    if (len > 0)
        sha256_update(ctx, (const uint8_t *)value, len);
}

static bool
api_resource_ref_aggregate_digest(const api_resource_ref_aggregate_t *aggregate,
                                  char hex[65])
{
    sha256_ctx_t ctx;
    uint8_t digest[SHA256_DIGEST_SIZE];
    uint i;

    if (hex == NULL)
        return false;
    hex[0] = '\0';
    if (aggregate == NULL || !aggregate->active || !aggregate->complete ||
        aggregate->entry_count == 0)
        return false;

    sha256_init(&ctx);
    sha256_update_u64_le(&ctx, aggregate->entry_count);
    for (i = 0; i < aggregate->entry_count; ++i) {
        const api_resource_ref_t *ref = &aggregate->entries[i];
        sha256_update_u64_le(&ctx, ref->arg_index);
        sha256_update_u64_le(&ctx, ref->handle_captured ? 1 : 0);
        sha256_update_u64_le(&ctx, (uint64_t)ref->handle);
        sha256_update_u64_le(&ctx, ref->resource_known ? 1 : 0);
        sha256_update_string_field(&ctx, ref->role);
        sha256_update_string_field(&ctx, ref->resource_known ? ref->kind : "");
        sha256_update_string_field(&ctx, ref->resource_known ? ref->label : "");
    }
    sha256_final(&ctx, digest);
    sha256_digest_hex(digest, hex);
    return true;
}

static bool
api_resource_ref_aggregate_complete(const api_resource_ref_aggregate_t *aggregate)
{
    char digest[65];
    uint i;
    if (aggregate == NULL || !aggregate->active)
        return true;
    if (!api_resource_ref_aggregate_digest(aggregate, digest))
        return false;
    for (i = 0; i < aggregate->entry_count; ++i) {
        if (!aggregate->entries[i].resource_known)
            return false;
    }
    return true;
}

static bool
api_resource_refs_complete(const api_call_effect_t *effect)
{
    uint i;
    if (effect == NULL)
        return false;
    if (effect->resource_ref_count == 0 && !effect->resource_ref_aggregate.active)
        return false;
    if (effect->resource_ref_dropped != 0 ||
        !api_resource_ref_aggregate_complete(&effect->resource_ref_aggregate))
        return false;
    for (i = 0; i < effect->resource_ref_count; ++i) {
        if (!effect->resource_refs[i].resource_known)
            return false;
    }
    return true;
}

static void
append_api_resource_ref(char **cursor, char *limit, const api_resource_ref_t *ref)
{
    append_raw(cursor, limit, "{\"arg_index\":");
    append_u64(cursor, limit, (unsigned long long)ref->arg_index);
    append_raw(cursor, limit, ",\"role\":");
    append_json_string(cursor, limit, ref->role);
    append_raw(cursor, limit, ",\"handle\":");
    if (ref->handle_captured)
        append_u64(cursor, limit, (unsigned long long)ref->handle);
    else
        append_raw(cursor, limit, "null");
    append_raw(cursor, limit, ",\"known\":");
    append_bool(cursor, limit, ref->resource_known);
    append_raw(cursor, limit, ",\"kind\":");
    append_json_string(cursor, limit, ref->resource_known ? ref->kind : "");
    append_raw(cursor, limit, ",\"label\":");
    append_json_string(cursor, limit, ref->resource_known ? ref->label : "");
    append_raw(cursor, limit, "}");
}

static void
append_api_resource_ref_aggregate(char **cursor, char *limit,
                                  const api_resource_ref_aggregate_t *aggregate)
{
    char digest[65];
    bool digest_ok = api_resource_ref_aggregate_digest(aggregate, digest);
    uint i;

    append_raw(cursor, limit, "\"resource_ref_aggregate\":{\"count\":");
    append_u64(cursor, limit,
               (unsigned long long)(aggregate != NULL && aggregate->active ?
                                    aggregate->entry_count : 0));
    append_raw(cursor, limit, ",\"sha256\":");
    append_json_string(cursor, limit, digest_ok ? digest : "");
    append_raw(cursor, limit, ",\"sha256_ok\":");
    append_bool(cursor, limit, digest_ok);
    append_raw(cursor, limit, ",\"entries\":[");
    if (aggregate != NULL) {
        for (i = 0; i < aggregate->entry_count; ++i) {
            if (i > 0)
                append_raw(cursor, limit, ",");
            append_api_resource_ref(cursor, limit, &aggregate->entries[i]);
        }
    }
    append_raw(cursor, limit, "]}");
}

