static void
append_api_calls(char **cursor, char *limit, const block_state_thread_t *effects)
{
    uint i;
    bool first = true;
    api_call_overflow_t *node;
    append_raw(cursor, limit, "\"api_calls\":[");
    for (i = 0; i < effects->api_call_count; ++i) {
        if (!first)
            append_raw(cursor, limit, ",");
        first = false;
        append_api_call_effect(cursor, limit, &effects->api_calls[i]);
    }
    for (node = effects->api_call_overflows; node != NULL; node = node->next) {
        if (!first)
            append_raw(cursor, limit, ",");
        first = false;
        append_api_call_effect(cursor, limit, &node->effect);
    }
    append_raw(cursor, limit, "]");
}

static void
append_api_returns(char **cursor, char *limit, const block_state_thread_t *effects)
{
    uint i;
    bool first = true;
    api_call_overflow_t *node;
    append_raw(cursor, limit, "\"api_returns\":[");
    for (i = 0; i < effects->api_call_count; ++i) {
        const api_call_effect_t *effect = &effects->api_calls[i];
        if (!effect->return_captured)
            continue;
        if (!first)
            append_raw(cursor, limit, ",");
        first = false;
        append_raw(cursor, limit, "{\"caller_rva\":");
        append_u64(cursor, limit, (unsigned long long)effect->caller_rva);
        append_raw(cursor, limit, ",\"return_value\":");
        append_u64(cursor, limit, (unsigned long long)effect->return_value);
        append_raw(cursor, limit, "}");
    }
    for (node = effects->api_call_overflows; node != NULL; node = node->next) {
        const api_call_effect_t *effect = &node->effect;
        if (!effect->return_captured)
            continue;
        if (!first)
            append_raw(cursor, limit, ",");
        first = false;
        append_raw(cursor, limit, "{\"caller_rva\":");
        append_u64(cursor, limit, (unsigned long long)effect->caller_rva);
        append_raw(cursor, limit, ",\"return_value\":");
        append_u64(cursor, limit, (unsigned long long)effect->return_value);
        append_raw(cursor, limit, "}");
    }
    append_raw(cursor, limit, "]");
}

